from fractions import Fraction as F
rows=[('A',15,(1,0,0,1)),('A',9,(0,1,1,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('C',9,(1,1,1,1)),('C',5,(0,1,1,0)),('D',14,(0,0,0,0)),('D',9,(1,1,1,0))]
tests='TUVW'; costs=list(map(F,['0.8','1.2','0.7','1.4']))
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def stop(ids):
 w=sum(rows[i][1] for i in ids)
 return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in ids),w),'ABCD'[a]) for a in range(4))
def solve(ids,available,budget):
 best,action=stop(ids)
 if budget:
  w=sum(rows[i][1] for i in ids)
  for t in available:
   val=costs[t]
   for v in (0,1):
    sub=[i for i in ids if rows[i][2][t]==v]
    if sub: val+=F(sum(rows[i][1] for i in sub),w)*solve(sub,[x for x in available if x!=t],budget-1)[0]
   if val<best: best,action=val,tests[t]
 return best,action
ids=list(range(8)); w=sum(r[1] for r in rows)
first={'STOP':float(stop(ids)[0])}
for t in range(4):
 val=costs[t]
 for v in (0,1):
  sub=[i for i in ids if rows[i][2][t]==v]
  val+=F(sum(rows[i][1] for i in sub),w)*solve(sub,[x for x in range(4) if x!=t],1)[0]
 first[tests[t]]=float(val)
best,action=solve(ids,list(range(4)),2)
nexts={}
if action in tests:
 t=tests.index(action)
 for v in (0,1):
  sub=[i for i in ids if rows[i][2][t]==v]
  nexts[str(v)]=solve(sub,[x for x in range(4) if x!=t],1)[1] if sub else 'IMPOSSIBLE'
print({'first':action,'first_losses':first,'next':nexts})

