from fractions import Fraction as F
rows=[('A',15,(1,0,0,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('D',14,(0,0,0,0))]
loss={'A':[0,24,11,6],'B':[19,0,19,8],'C':[9,10,0,16],'D':[21,24,20,0]}
def repairs(rs):
 total=sum(r[1] for r in rs)
 return {a:F(sum(r[1]*ls['ABCD'.index(r[0])] for r in rs),total) for a,ls in loss.items()}
total=sum(r[1] for r in rows)
post={a:float(F(sum(r[1] for r in rows if r[0]==a),total)) for a in 'ABCD'}
remaining=repairs(rows); branches={}
for t,j,cost in [('T',0,F('0.8')),('U',1,F('1.2')),('W',3,F('7.4'))]:
 val=cost; branches[t]={}
 for v in [0,1]:
  sub=[r for r in rows if r[2][j]==v]
  if not sub: branches[t][str(v)]='IMPOSSIBLE'; continue
  choices=repairs(sub); a=min(choices,key=choices.get)
  val+=F(sum(r[1] for r in sub),total)*choices[a]
  branches[t][str(v)]=a
 remaining[t]=val
a=min(remaining,key=remaining.get)
print({'posterior':post,'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':a,'repair_after':branches.get(a,{})})

